-- 000 T110: sự kiện ở gốc api của approval, correction, parameter chuyển vào api.events (research R-02,
-- backend/README mục 4). Spring Modulith lưu tên lớp đầy đủ của sự kiện và listener; đổi theo để các sự kiện
-- chưa hoàn tất vẫn được xử lý lại (mẫu V000_09).
UPDATE EVENT_PUBLICATION
SET LISTENER_ID = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(LISTENER_ID, 'com.eldercare.backend.administration.approval.api.ApproverReminderDue', 'com.eldercare.backend.administration.approval.api.events.ApproverReminderDue'), 'com.eldercare.backend.administration.approval.api.ManagerEscalationDue', 'com.eldercare.backend.administration.approval.api.events.ManagerEscalationDue'), 'com.eldercare.backend.administration.approval.api.RequestApplied', 'com.eldercare.backend.administration.approval.api.events.RequestApplied'), 'com.eldercare.backend.administration.approval.api.RequestApplyFailed', 'com.eldercare.backend.administration.approval.api.events.RequestApplyFailed'), 'com.eldercare.backend.administration.approval.api.RequestCancelled', 'com.eldercare.backend.administration.approval.api.events.RequestCancelled'), 'com.eldercare.backend.administration.approval.api.RequestCreated', 'com.eldercare.backend.administration.approval.api.events.RequestCreated'), 'com.eldercare.backend.administration.approval.api.RequestDecided', 'com.eldercare.backend.administration.approval.api.events.RequestDecided'), 'com.eldercare.backend.administration.approval.api.RequestSubmitted', 'com.eldercare.backend.administration.approval.api.events.RequestSubmitted'), 'com.eldercare.backend.administration.correction.api.CorrectionMade', 'com.eldercare.backend.administration.correction.api.events.CorrectionMade'), 'com.eldercare.backend.administration.parameter.api.ParameterChanged', 'com.eldercare.backend.administration.parameter.api.events.ParameterChanged'),
    EVENT_TYPE  = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(EVENT_TYPE, 'com.eldercare.backend.administration.approval.api.ApproverReminderDue', 'com.eldercare.backend.administration.approval.api.events.ApproverReminderDue'), 'com.eldercare.backend.administration.approval.api.ManagerEscalationDue', 'com.eldercare.backend.administration.approval.api.events.ManagerEscalationDue'), 'com.eldercare.backend.administration.approval.api.RequestApplied', 'com.eldercare.backend.administration.approval.api.events.RequestApplied'), 'com.eldercare.backend.administration.approval.api.RequestApplyFailed', 'com.eldercare.backend.administration.approval.api.events.RequestApplyFailed'), 'com.eldercare.backend.administration.approval.api.RequestCancelled', 'com.eldercare.backend.administration.approval.api.events.RequestCancelled'), 'com.eldercare.backend.administration.approval.api.RequestCreated', 'com.eldercare.backend.administration.approval.api.events.RequestCreated'), 'com.eldercare.backend.administration.approval.api.RequestDecided', 'com.eldercare.backend.administration.approval.api.events.RequestDecided'), 'com.eldercare.backend.administration.approval.api.RequestSubmitted', 'com.eldercare.backend.administration.approval.api.events.RequestSubmitted'), 'com.eldercare.backend.administration.correction.api.CorrectionMade', 'com.eldercare.backend.administration.correction.api.events.CorrectionMade'), 'com.eldercare.backend.administration.parameter.api.ParameterChanged', 'com.eldercare.backend.administration.parameter.api.events.ParameterChanged')
WHERE EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.ApproverReminderDue%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.ManagerEscalationDue%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.RequestApplied%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.RequestApplyFailed%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.RequestCancelled%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.RequestCreated%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.RequestDecided%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.approval.api.RequestSubmitted%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.correction.api.CorrectionMade%'
   OR EVENT_TYPE LIKE '%com.eldercare.backend.administration.parameter.api.ParameterChanged%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.ApproverReminderDue%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.ManagerEscalationDue%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.RequestApplied%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.RequestApplyFailed%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.RequestCancelled%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.RequestCreated%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.RequestDecided%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.approval.api.RequestSubmitted%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.correction.api.CorrectionMade%'
   OR LISTENER_ID LIKE '%com.eldercare.backend.administration.parameter.api.ParameterChanged%';
